    @Test
    fun fixedPointVectors() {
        assertEquals(-1L, Fx.mul(-1L, 1L))
        assertEquals(Fx.RAW_MAX, Fx.mul(Fx.RAW_MAX, Fx.RAW_MAX))
        assertEquals(Fx.RAW_MAX, Fx.mul(Fx.RAW_MIN, Fx.RAW_MIN))
        assertEquals(-2L, Fx.mul(-3L, 32768L))
        assertEquals(-2L, Fx.mul(3L, -32768L))
        assertEquals(21845L, Fx.div(65536L, 196608L))
        assertEquals(-21845L, Fx.div(-65536L, 196608L))
        assertEquals(-21845L, Fx.div(65536L, -196608L))
        assertEquals(Fx.RAW_MAX, Fx.div(5L, 0L))
        assertEquals(Fx.RAW_MIN, Fx.div(-5L, 0L))
        assertEquals(0L, Fx.div(0L, 0L))
        assertEquals(Fx.RAW_MAX, Fx.div(Fx.RAW_MIN, -1L))
        assertEquals(Fx.RAW_MAX, Fx.neg(Fx.RAW_MIN))
        assertEquals(Fx.RAW_MAX, Fx.add(Fx.RAW_MAX, 1L))
        assertEquals(Fx.RAW_MIN, Fx.sub(Fx.RAW_MIN, 1L))
        // Operands outside the raw range are saturated first: no wrap, no trap.
        assertEquals(Fx.RAW_MAX, Fx.add(Long.MAX_VALUE, 1L))
        assertEquals(Fx.RAW_MIN, Fx.sub(Long.MIN_VALUE, Long.MAX_VALUE))
        assertEquals(Fx.RAW_MAX, Fx.neg(Long.MIN_VALUE))
        assertEquals(Fx.RAW_MAX, Fx.mul(Long.MAX_VALUE, Long.MAX_VALUE))
        assertEquals(Fx.RAW_MIN, Fx.mul(Long.MIN_VALUE, 65536L))
        assertEquals(Fx.RAW_MAX, Fx.div(Long.MAX_VALUE, 1L))
        assertEquals(0L, Fx.div(1L, Long.MIN_VALUE))
    }

    @Test
    fun randomnessVectors() {
        val ref = Pcg32(42uL, 54uL)
        assertEquals(
            listOf(0xa15c02b7u, 0x7b47f409u, 0xba1d3330u, 0x83d2f293u, 0xbfa4784bu, 0xcbed606eu),
            List(6) { ref.nextU32() },
        )
        assertEquals(0x85944171f73967e8uL, fnv1a64("foobar".toByteArray(Charsets.UTF_8)))
        assertEquals(0xaf63dc4c8601ec8cuL, fnv1a64("a".toByteArray(Charsets.UTF_8)))

        val spawn = Pcg32.forStream(12345uL, "spawn")
        assertEquals(listOf(3836204951u, 2901556457u, 1288830458u, 20171900u), List(4) { spawn.nextU32() })
        assertEquals(0xbe81daf6f5b5d3bbuL, spawn.state)
        assertEquals(0x6f4a8582f6e4629fuL, spawn.inc)

        val fx = Pcg32.forStream(12345uL, "fx")
        assertEquals(listOf(3544770967u, 1588508108u, 78643710u, 1025764217u), List(4) { fx.nextU32() })

        val bounded = Pcg32.forStream(1uL, "spawn")
        assertEquals(listOf(6u, 0u, 2u, 2u, 1u, 0u, 3u, 7u), List(8) { bounded.nextBelow(10u) })
        assertEquals(listOf(0u, 0u), List(2) { bounded.nextBelow(1u) })
        assertEquals(1771058001u, bounded.nextBelow(1u shl 31))
    }

    private fun clockRun(rate: Int, max: Int, frames: List<Long>): Triple<List<Int>, Long, Long> {
        val c = FrameClock(rate, max)
        val ticks = frames.map { c.advance(it) }
        return Triple(ticks, c.remainder, c.alpha)
    }

    @Test
    fun frameClockVectors() {
        assertEquals(Triple(listOf(1, 1, 1, 1), 80L, 0L), clockRun(60, 5, List(4) { 16666667L }))
        assertEquals(Triple(listOf(0, 1, 1, 1), 999999840L, 65535L), clockRun(60, 5, List(4) { 16666666L }))
        assertEquals(Triple(listOf(0, 0, 1, 0, 1, 0), 999999880L, 65535L), clockRun(60, 5, List(6) { 8333333L }))
        assertEquals(Triple(listOf(5, 1), 20L, 0L), clockRun(60, 5, listOf(500000000L, 16666667L)))
        assertEquals(Triple(listOf(0, 0, 5), 0L, 0L), clockRun(60, 5, listOf(-5L, 0L, 2000000000L)))
        assertEquals(Triple(listOf(0), 499999980L, 32767L), clockRun(60, 5, listOf(8333333L)))
        assertEquals(Triple(listOf(60), 0L, 0L), clockRun(60, 100, listOf(2000000000L)))
        assertEquals(Triple(listOf(1, 1, 1), 0L, 0L), clockRun(120, 5, listOf(8333334L, 8333333L, 8333333L)))
        var x = 12345L
        val frames = List(1000) {
            x = (x * 1103515245L + 12345L) and 0x7FFFFFFFL
            4_000_000L + (x shr 8) % 36_000_000L
        }
        val c = FrameClock(60, 5)
        assertEquals(490, frames.sumOf { c.advance(it) })
        assertEquals(103339700L, c.remainder)
    }

    private fun idleReplayHash(seed: ULong, ticks: Int): ULong =
        replay(GeneratedRuntimeConfig.config, seed, ticks, emptyList(), listOf(ticks)).single().hash

    private fun newLoop(seed: ULong, maxTicks: Int = GeneratedRuntimeConfig.MAX_TICKS_PER_FRAME) =
        GameLoop(World(GeneratedRuntimeConfig.config, seed), GeneratedRuntimeConfig.TICK_RATE, maxTicks)

    @Test
    fun idleStateIsIndependentOfDisplayRateAndJitter() {
        for (hz in listOf(30, 60, 90, 120, 144)) {
            val loop = newLoop(7uL)
            var x = hz.toLong()
            for (i in 0 until 400) {
                x = (x * 1103515245L + 12345L) and 0x7FFFFFFFL
                loop.frame(1_000_000_000L / hz + (x shr 8) % 2_000_000L - 1_000_000L)
                if (i % 40 == 0) {
                    assertEquals("hz=$hz frame=$i", idleReplayHash(7uL, loop.world.tick.toInt()), loop.world.stateHash())
                }
            }
        }
    }

    @Test
    fun inputsApplyAtTheStartOfTheNextTickInOrder() {
        val loop = newLoop(9uL)
        val recorded = ArrayList<TickInput>()
        var x = 3L
        for (i in 0 until 600) {
            val events = ArrayList<InputEvent>()
            if (i % 7 == 0) events.add(InputEvent(InputType.TAP))
            if (i % 11 == 0) events.add(InputEvent(InputType.DRAG, ((i % 13) - 6) * 65536L, 0L))
            for (ev in events) {
                loop.submit(ev)
                recorded.add(TickInput(loop.world.tick.toInt(), listOf(ev)))
            }
            x = (x * 1103515245L + 12345L) and 0x7FFFFFFFL
            loop.frame(10_000_000L + (x shr 8) % 25_000_000L)
        }
        val ticks = loop.world.tick.toInt()
        // Some specs end early (lives run out); a finished world is a no-op in both loop and replay.
        assertTrue(ticks > 10)
        val want = replay(GeneratedRuntimeConfig.config, 9uL, ticks, recorded, listOf(ticks)).single().hash
        assertEquals(want, loop.world.stateHash())
    }

    @Test
    fun hitchIsCappedAndBacklogDropped() {
        val cap = GeneratedRuntimeConfig.MAX_TICKS_PER_FRAME
        val loop = newLoop(1uL, cap)
        assertEquals(cap, loop.frame(2_000_000_000L))
        assertEquals(0, loop.frame(1_000_000L))
    }

    private class Scenario(val name: String, val seed: ULong, val ticks: Int) {
        var frames: FrameSpec? = null
        val inputs = ArrayList<TickInput>()
        val expected = ArrayList<Checkpoint>()
    }

    private fun parseScenarios(): List<Scenario> {
        val stream = ConformanceTest::class.java.getResourceAsStream("/monstera-scenarios.txt")
        requireNotNull(stream) { "monstera-scenarios.txt is missing from the test resources" }
        val out = ArrayList<Scenario>()
        var current: Scenario? = null
        for (line in stream.bufferedReader().readLines()) {
            if (line.isEmpty() || line.startsWith("#") || line.startsWith("monstera-scenarios ")) continue
            val p = line.split(' ')
            when (p[0]) {
                "scenario" -> current = Scenario(p[1], p[2].toULong(), p[3].toInt())
                "frames" -> checkNotNull(current).frames = FrameSpec(p[1].toInt(), p[2].toLong(), p[3].toLong(), p[4].toLong())
                "input" -> {
                    val sc = checkNotNull(current)
                    val event = InputEvent(
                        InputType.valueOf(p[2].uppercase()), p[3].toLong(), p[4].toLong(), Direction.valueOf(p[5].uppercase()),
                    )
                    val tick = p[1].toInt()
                    val last = sc.inputs.lastOrNull()
                    if (last != null && last.tick == tick) {
                        sc.inputs[sc.inputs.size - 1] = TickInput(tick, last.events + event)
                    } else {
                        sc.inputs.add(TickInput(tick, listOf(event)))
                    }
                }
                "checkpoint" -> checkNotNull(current).expected.add(
                    Checkpoint(p[1].toInt(), p[2].toULong(16), p.subList(3, 9).map { it.toLong() }),
                )
                "end" -> { out.add(checkNotNull(current)); current = null }
                else -> error("unknown line: $line")
            }
        }
        return out
    }

    private fun hex(h: ULong): String = h.toString(16).padStart(16, '0')

    @Test
    fun goldenScenarios() {
        val scenarios = parseScenarios()
        val report = System.getenv("MONSTERA_CONFORMANCE_OUT")?.let { File(it) }
        val lines = ArrayList<String>()
        val failures = ArrayList<String>()
        for (sc in scenarios) {
            val spec = sc.frames
            val checkpointTicks = sc.expected.map { it.tick }
            val got = if (spec == null) {
                replay(GeneratedRuntimeConfig.config, sc.seed, sc.ticks, sc.inputs, checkpointTicks)
            } else {
                replayFrames(GeneratedRuntimeConfig.config, sc.seed, GeneratedRuntimeConfig.TICK_RATE,
                    GeneratedRuntimeConfig.MAX_TICKS_PER_FRAME, spec, sc.inputs, checkpointTicks)
            }
            for (g in got) {
                lines.add(
                    "{\"platform\":\"kotlin\",\"scenario\":\"${sc.name}\",\"tick\":${g.tick},\"hash\":\"${hex(g.hash)}\"," +
                        "\"observe\":[${g.observe.joinToString(",")}]}",
                )
            }
            val bad = sc.expected.zip(got).firstOrNull { (want, have) -> want != have }
            if (bad != null) {
                val fields = observableNames.indices.filter { bad.first.observe[it] != bad.second.observe[it] }
                    .joinToString { observableNames[it] }
                failures.add("${sc.name}: first divergence at tick ${bad.first.tick} (hash ${hex(bad.first.hash)} vs ${hex(bad.second.hash)}; fields: ${fields.ifEmpty { "hash only" }})")
            } else if (got.size != sc.expected.size) {
                failures.add("${sc.name}: produced ${got.size} checkpoints, expected ${sc.expected.size}")
            }
        }
        report?.writeText(lines.joinToString("\n") + "\n")
        assertTrue("no scenarios found", scenarios.isNotEmpty())
        assertTrue(failures.joinToString("\n"), failures.isEmpty())
    }
